@RestController
@RequestMapping("/users")
public class UserController {
    private static final String SESSION_USER = "loggedInUser";

    @Autowired
    private UserService userService;

    @PostMapping("/update-email")
    public ResponseEntity<String> updateEmail(@RequestParam String newEmail, HttpServletRequest request) {
        HttpSession session = request.getSession();
        User currentUser = (User) session.getAttribute(SESSION_USER);

        if (currentUser == null) {
            return ResponseEntity.status(401).body("未登录");
        }

        // 直接更新邮箱，未校验 CSRF token
        userService.updateEmail(currentUser.getId(), newEmail);
        return ResponseEntity.ok("邮箱更新成功");
    }

    @PostMapping("/change-password")
    public ResponseEntity<String> changePassword(@RequestParam String oldPwd, 
                                                 @RequestParam String newPwd, 
                                                 HttpServletRequest request) {
        HttpSession session = request.getSession();
        User currentUser = (User) session.getAttribute(SESSION_USER);

        if (currentUser == null) {
            return ResponseEntity.status(401).body("未登录");
        }

        // 密码修改操作同样缺少 CSRF 防护
        if (!userService.checkPassword(currentUser.getId(), oldPwd)) {
            return ResponseEntity.status(400).body("原密码错误");
        }

        userService.updatePassword(currentUser.getId(), newPwd);
        return ResponseEntity.ok("密码修改成功");
    }
}

