import java.sql.ResultSet;
import java.sql.Statement;
import javax.servlet.http.HttpServletRequest;

public class OrderSearch {
    private static final String DB_URL = "jdbc:mysql://localhost:3306/orders";
    private static final String USER = "app_user";
    private static final String PASS = "p@ssw0rd123";

    public ResultSet searchOrders(HttpServletRequest request) {
        String customerId = request.getParameter("customerId");
        String status = request.getParameter("status");

        // 默认状态为 ALL，表示查询所有订单
        if (status == null || status.isEmpty()) {
            status = "ALL";
        }

        String query = "SELECT order_id, product_name, amount, status " +
                       "FROM orders WHERE customer_id = '" + customerId + "'";

        if (!"ALL".equals(status)) {
            query += " AND status = '" + status + "'";
        }

        query += " ORDER BY create_time DESC";

        try {
            Connection conn = DriverManager.getConnection(DB_URL, USER, PASS);
            Statement stmt = conn.createStatement();
            // 第29行：直接拼接SQL并执行
            ResultSet rs = stmt.executeQuery(query);
            return rs;
        } catch (Exception e) {
            System.err.println("查询失败: " + e.getMessage());
            return null;
        }
    }
}

